#[no_mangle]
pub unsafe extern "C" fn begin_diagnostic() {
    old_setting = selector as ::core::ffi::c_uchar;
    if (*eqtb.offset((INT_BASE + INT_PAR__tracing_online) as isize))
        .b32
        .s1
        <= 0 as int32_t
        && selector as ::core::ffi::c_uint
            == SELECTOR_TERM_AND_LOG as ::core::ffi::c_int as ::core::ffi::c_uint
    {
        selector -= 1;
        if history as ::core::ffi::c_uint
            == HISTORY_SPOTLESS as ::core::ffi::c_int as ::core::ffi::c_uint
        {
            history = HISTORY_WARNING_ISSUED;
        }
    }
}
#[no_mangle]
pub unsafe extern "C" fn end_diagnostic(mut blank_line: bool) {
    print_nl_cstr(b"\0" as *const u8 as *const ::core::ffi::c_char);
    if blank_line {
        print_ln();
    }
    selector = old_setting as selector_t;
}
