static mut PITEX_COLOR_STACK_NUMBER: i32 = 1;
unsafe fn pitex_colorstack_initialize() {
    let page = if scan_keyword(b"page\0".as_ptr().cast()) { "page " } else { "" };
    let direct = if scan_keyword(b"direct\0".as_ptr().cast()) { "direct " } else { "" };
    let saved_def = def_ref;
    let saved_scanner = scanner_status;
    let saved_warning = warning_index;
    let text = pitex_scan_pdf_text();
    def_ref = saved_def; scanner_status = saved_scanner; warning_index = saved_warning;
    let number = PITEX_COLOR_STACK_NUMBER; PITEX_COLOR_STACK_NUMBER += 1;
    pitex_append_global_special(&format!("pdfcolorstackinit {} {}{}({})",number,page,direct,text));
    pitex_insert_text(&number.to_string());
}
unsafe fn pitex_colorstack() {
    scan_int(); let number = cur_val;
    let action = if scan_keyword(b"push\0".as_ptr().cast()) { "push" }
        else if scan_keyword(b"pop\0".as_ptr().cast()) { "pop" }
        else if scan_keyword(b"current\0".as_ptr().cast()) { "current" }
        else { scan_keyword(b"set\0".as_ptr().cast()); "set" };
    let text = if action == "set" || action == "push" { format!("({})",pitex_scan_pdf_text()) } else { String::new() };
    pitex_append_special(&format!("pdfcolorstack {} {} {}",number,action,text));
}

unsafe fn pitex_glyph_mapping() {
    let list=pitex_parameter_location(b"PitexGlyphUnicodeMappings\0".as_ptr().cast(),ASSIGN_TOKS).expect("registered glyph mapping token storage");
    let tail=pitex_parameter_location(b"PitexGlyphUnicodeTail\0".as_ptr().cast(),ASSIGN_INT).expect("registered glyph mapping tail storage");
    let version=pitex_parameter_location(b"PitexGlyphUnicodeVersion\0".as_ptr().cast(),ASSIGN_INT).expect("registered glyph mapping version storage");
    let saved_def=def_ref;let saved_scanner=scanner_status;let saved_warning=warning_index;
    let saved_string=if pool_ptr>*str_start.offset((str_ptr-TOO_BIG_CHAR as str_number) as isize){make_string()}else{0};
    let glyph=pitex_scan_pdf_text();let unicode=pitex_scan_pdf_text();
    let text=std::ffi::CString::new(format!("{} {} ",pitex_pdf_string(&glyph),pitex_pdf_string(&unicode))).unwrap();
    let node=pitex_special_node(text.as_ptr());let reference=(*mem.offset((node+1) as isize)).b32.s1;
    free_node(node,WRITE_NODE_SIZE as i32);
    def_ref=saved_def;scanner_status=saved_scanner;warning_index=saved_warning;
    if saved_string!=0 {str_ptr-=1;}
    let original=(*eqtb.offset(list as isize)).b32.s1;
    let glyph_head=(*mem.offset(reference as isize)).b32.s1;
    let mut glyph_tail=glyph_head;while (*mem.offset(glyph_tail as isize)).b32.s1 != TEX_NULL as i32 {glyph_tail=(*mem.offset(glyph_tail as isize)).b32.s1;}
    if original==TEX_NULL as i32 {geq_define(list,CALL as uint16_t,reference);}
    else {
        let previous=(*eqtb.offset(tail as isize)).b32.s1;
        (*mem.offset(previous as isize)).b32.s1=glyph_head;
        (*mem.offset(reference as isize)).b32.s1=avail;avail=reference;
    }
    geq_word_define(tail,glyph_tail);
    geq_word_define(version,(*eqtb.offset(version as isize)).b32.s1.saturating_add(1));
}
unsafe fn pitex_pdf_structure(code:i32) {
    match code {
        170|171 => {
            let mut dimensions=pitex_pdf_dimensions();
            let attr=if scan_keyword(b"attr\0".as_ptr().cast()){pitex_scan_pdf_text()}else{String::new()};
            let identifier=if scan_keyword(b"name\0".as_ptr().cast()){format!("name {}",pitex_pdf_string(&pitex_scan_pdf_text()))}
                else{scan_keyword(b"num\0".as_ptr().cast());scan_int();format!("num {}",cur_val)};
            if abs(cur_list.mode as i32)==VMODE {dimensions=regex::Regex::new(r"depth [-+0-9.]+pt ").unwrap().replace_all(&dimensions,"").into_owned();dimensions.push_str("depth 0pt ");}
            pitex_append_special(&format!("pdf:{} {} {} << {} >>",if code==170{"thread"}else{"bthread"},identifier,dimensions,attr));
        },
        172=>pitex_append_special("pdf:ethread"),
        173=>pitex_append_special("pdf:runninglink off"),
        174=>pitex_append_special("pdf:runninglink on"),
        _=>unreachable!()
    }
}
unsafe fn pitex_pdf_extension(code: int32_t) {
    match code {
        100 => {
            let mode = if scan_keyword(b"direct\0".as_ptr().cast()) { "direct " }
                       else if scan_keyword(b"page\0".as_ptr().cast()) { "page " } else { "" };
            let body = pitex_scan_pdf_text();
            pitex_append_special(&format!("pdf:literal {}{}", mode, body));
        }
        101 => {
            if scan_keyword(b"reserveobjnum\0".as_ptr().cast()) {
                PITEX_PDF_LAST_OBJECT = pitex_allocate_object();
                PITEX_PDF_RESERVED_OBJECTS.insert(PITEX_PDF_LAST_OBJECT);
                return;
            }
            let using_reserved=scan_keyword(b"useobjnum\0".as_ptr().cast());
            let object=if using_reserved {scan_int();cur_val}else{pitex_allocate_object()};
            let body = pitex_scan_pdf_text();
            if using_reserved && !PITEX_PDF_RESERVED_OBJECTS.remove(&object) {crate::engine_strings::invalid_pdf_object();return;}
            PITEX_PDF_LAST_OBJECT = object;
            pitex_append_global_special(&format!("pdf:obj @pitexobj{} {}", object, body));
        }
        102 => {
            scan_int();
            pitex_append_special(&format!("pdf:refobj @pitexobj{}", cur_val));
        }
        103 => {
            let body = pitex_scan_pdf_text();
            pitex_append_global_special(&format!("pdf:info << {} >>", body));
        }
        104 => {
            let body = pitex_scan_pdf_text();
            pitex_append_global_special(&format!("pdf:pdftexcatalog << {} >>", body));
        }
        105 => pitex_append_special("pdf:literal direct q"),
        106 => pitex_append_special("pdf:literal direct Q"),
        107 => {
            let body = pitex_scan_pdf_text();
            pitex_append_special(&format!("pdf:pdftexmatrix {}", body));
        }

        108 => {
            let dimensions = pitex_pdf_dimensions();
            let body = pitex_scan_pdf_text();
            PITEX_PDF_LAST_ANNOTATION=pitex_allocate_object();
            pitex_append_special(&format!("pdf:ann @pitexobj{} {} << {} >>", PITEX_PDF_LAST_ANNOTATION, dimensions, body));
        }
        109 => {
            let dimensions = pitex_pdf_dimensions();
            let attr = if scan_keyword(b"attr\0".as_ptr().cast()) { pitex_scan_pdf_text() } else { String::new() };
            let action = if scan_keyword(b"user\0".as_ptr().cast()) { pitex_scan_pdf_text() }
                else if scan_keyword(b"goto\0".as_ptr().cast()) {
                    let destination = pitex_pdf_destination_name();
                    format!("/A << /S /GoTo /D {} >>", destination)
                } else { pitex_scan_pdf_text() };
            PITEX_PDF_LAST_LINK=pitex_allocate_object();
            pitex_append_special(&format!("pdf:pitexbann @pitexobj{} {} << /Type /Annot /Subtype /Link {} {} >>", PITEX_PDF_LAST_LINK, dimensions, attr, action));
        }
        110 => pitex_append_special("pdf:eann"),
        111 => {
            let name = pitex_pdf_destination_name();
            if scan_keyword(b"fitr\0".as_ptr().cast()) {
                let dimensions=pitex_pdf_dimensions();
                pitex_append_special(&format!("pdf:fitrdest {} {}",name,dimensions));return;
            }
            let view = if scan_keyword(b"xyz\0".as_ptr().cast()) { "XYZ @xpos @ypos null" }
                else if scan_keyword(b"fitbh\0".as_ptr().cast()) { "FitBH @ypos" }
                else if scan_keyword(b"fitbv\0".as_ptr().cast()) { "FitBV @xpos" }
                else if scan_keyword(b"fith\0".as_ptr().cast()) { "FitH @ypos" }
                else if scan_keyword(b"fitv\0".as_ptr().cast()) { "FitV @xpos" }
                else if scan_keyword(b"fitb\0".as_ptr().cast()) { "FitB" }
                else { scan_keyword(b"fit\0".as_ptr().cast()); "Fit" };
            pitex_append_special(&format!("pdf:dest {} [ @thispage /{} ]", name, view));
        }
        112 => pitex_make_xform(),
        113 => pitex_use_xform(),
        114 => pitex_make_ximage(),
        115 => pitex_use_ximage(),
        116 => pitex_outline(),
        117 => pitex_colorstack(),
        118 | 119 => { let body = pitex_scan_pdf_text(); pitex_append_global_special(&format!("pdf:{} {}", if code==118 {"mapline"} else {"mapfile"},pitex_pdf_string(&body))); },
        120 => { let body = pitex_scan_pdf_text(); pitex_append_global_special(&format!("pdf:pdftexnames << {} >>",body)); },
        121 => { let body = pitex_scan_pdf_text(); pitex_append_global_special(&format!("pdf:pdftextrailer << {} >>",body)); },
        122 => {
            // pdfTeX writes /ID [<md5> <md5>] from the text and omits it for empty text.
            let body = pitex_scan_pdf_text();
            let mut id = String::new();
            if !body.is_empty() {
                let mut digest = [0u8; 16];
                ttbc_get_data_md5(body.as_ptr(), body.len(), digest.as_mut_ptr());
                let hex: String = digest.iter().map(|byte| format!("{byte:02X}")).collect();
                id = format!("[<{hex}> <{hex}>]");
            }
            pitex_append_global_special(&format!("pdf:pdftextrailerid {}",id));
        },
        _ => unreachable!(),
    }
}

