#[no_mangle]
pub unsafe extern "C" fn insert_src_special() {
    let mut toklist: int32_t = 0;
    let mut p: int32_t = 0;
    let mut q: int32_t = 0;
    if *source_filename_stack.offset(in_open as isize) > 0 as str_number
        && is_new_source(
            *source_filename_stack.offset(in_open as isize),
            line as ::core::ffi::c_int,
        ) as ::core::ffi::c_int
            != 0
    {
        toklist = get_avail();
        p = toklist;
        (*mem.offset(p as isize)).b32.s0 = (CS_TOKEN_FLAG + FROZEN_SPECIAL) as int32_t;
        (*mem.offset(p as isize)).b32.s1 = get_avail();
        p = (*mem.offset(p as isize)).b32.s1;
        (*mem.offset(p as isize)).b32.s0 = (LEFT_BRACE_TOKEN + '{' as i32) as int32_t;
        q = str_toks(make_src_special(
            *source_filename_stack.offset(in_open as isize),
            line as ::core::ffi::c_int,
        ));
        (*mem.offset(p as isize)).b32.s1 = (*mem.offset(TEMP_HEAD as isize)).b32.s1;
        p = q;
        (*mem.offset(p as isize)).b32.s1 = get_avail();
        p = (*mem.offset(p as isize)).b32.s1;
        (*mem.offset(p as isize)).b32.s0 = (RIGHT_BRACE_TOKEN + '}' as i32) as int32_t;
        begin_token_list(toklist, INSERTED as uint16_t);
        remember_source_info(
            *source_filename_stack.offset(in_open as isize),
            line as ::core::ffi::c_int,
        );
    }
}
#[no_mangle]
